const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const caboFrio = ee.Geometry.Point([-42.02, -22.88]);
  const searchArea = caboFrio.buffer(20000); // 20km radius for sea zone

  const startDate = '2023-09-01';
  const endDate = '2023-09-30';

  // 2. Data Acquisition - Try MODIS Aqua SST first
  let sstCol = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate(startDate, endDate)
    .filterBounds(searchArea)
    .select('sst');

  let colSize = sstCol.size().getInfo();
  console.log('MODIS Aqua SST Images: ' + colSize);

  if (colSize === 0) {
    // Try NOAA SST as backup
    sstCol = ee.ImageCollection('NOAA/CDR/OISST/V2_1')
      .filterDate(startDate, endDate)
      .filterBounds(searchArea)
      .select('sst');

    colSize = sstCol.size().getInfo();
    console.log('NOAA SST Images: ' + colSize);

    if (colSize === 0) {
      console.log('No SST data found for September 2023.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Create composite to analyze
  const sstMean = sstCol.mean();

  // 4. Sample along transects perpendicular to coast (offshore direction)
  // Cabo Frio is known for upwelling - cold water near coast, warm offshore
  const coastPoint = ee.Geometry.Point([-42.02, -22.88]); // Near coast
  const offshore5km = ee.Geometry.Point([-41.97, -22.88]); // ~5km offshore
  const offshore10km = ee.Geometry.Point([-41.92, -22.88]); // ~10km offshore
  const offshore15km = ee.Geometry.Point([-41.87, -22.88]); // ~15km offshore

  // Sample temperatures
  const samplingPoints = ee.FeatureCollection([
    ee.Feature(coastPoint, {name: 'coast'}),
    ee.Feature(offshore5km, {name: 'off5km'}),
    ee.Feature(offshore10km, {name: 'off10km'}),
    ee.Feature(offshore15km, {name: 'off15km'})
  ]);

  const samples = sstMean.sampleRegions({
    collection: samplingPoints,
    scale: 1000,
    geometries: true
  });

  const sampleList = samples.toList(10).getInfo();

  if (sampleList.length === 0) {
    console.log('No valid SST pixels in sampling area.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Extract temperatures and check gradients
  const temps = {};
  for (let i = 0; i < sampleList.length; i++) {
    const feature = sampleList[i];
    const name = feature.properties.name;
    const temp = feature.properties.sst;
    temps[name] = temp;
    console.log(name + ' SST: ' + (temp !== null ? temp.toFixed(2) + '°C' : 'null'));
  }

  // Check if we have valid temperatures
  const validTemps = Object.values(temps).filter(t => t !== null && !isNaN(t));
  if (validTemps.length < 2) {
    console.log('Insufficient valid temperature data.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Calculate gradients over different distances
  let maxGradient = 0;
  let gradientDistance = 0;

  if (temps.coast !== null && temps.off5km !== null) {
    const grad5 = Math.abs(temps.coast - temps.off5km);
    console.log('Gradient 0-5km: ' + grad5.toFixed(2) + '°C');
    if (grad5 > maxGradient) {
      maxGradient = grad5;
      gradientDistance = 5;
    }
  }

  if (temps.off5km !== null && temps.off10km !== null) {
    const grad10 = Math.abs(temps.off5km - temps.off10km);
    console.log('Gradient 5-10km: ' + grad10.toFixed(2) + '°C');
    if (grad10 > maxGradient) {
      maxGradient = grad10;
      gradientDistance = 5;
    }
  }

  if (temps.coast !== null && temps.off10km !== null) {
    const grad10total = Math.abs(temps.coast - temps.off10km);
    console.log('Gradient 0-10km: ' + grad10total.toFixed(2) + '°C');
    if (grad10total > maxGradient && grad10total / 10 > maxGradient / gradientDistance) {
      maxGradient = grad10total;
      gradientDistance = 10;
    }
  }

  console.log('Max gradient: ' + maxGradient.toFixed(2) + '°C over ' + gradientDistance + 'km');

  // 6. Final Answer
  if (maxGradient > 5 && gradientDistance <= 10) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
